from csv import DictReader
from decimal import Decimal


CATALOG_PATH = "/app/dataset/product_catalog.csv"
DISPATCHES_PATH = "/app/dataset/warehouse_dispatches.csv"
DISPOSAL_TIMESTAMP = "2023-07-18 03:17:00"


def _money(value: str) -> Decimal:
    return Decimal(value.replace(",", "."))


def _price_lookup() -> dict[str, Decimal]:
    prices: dict[str, Decimal] = {}
    with open(CATALOG_PATH, newline="") as f:
        for row in DictReader(f):
            price = _money(row["unit_price"])
            prices[row["product_id"]] = price
            prices[row["ean_code"]] = price
    return prices


def answer() -> int:
    prices = _price_lookup()
    revenue = Decimal("0")

    with open(DISPATCHES_PATH, newline="") as f:
        for row in DictReader(f):
            # The July 18 03:17 cold-chain batch coincides with the only
            # temperature excursion and is the disposal write-off trace.
            if row["timestamp"] == DISPOSAL_TIMESTAMP:
                continue
            revenue += int(row["quantity"]) * prices[row["product_id"]]

    return int(revenue)


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
